class StarOrAnyDeepLoopTraceTest {
    private fun dumpDemand(config: org.opentaint.dataflow.bidi.engine.RunConfig) {
        val demand = config.demand ?: return
        val type = demand.javaClass
        for (field in listOf("byMethod", "controls", "scoped")) {
            val entries = type.getDeclaredField(field).apply { isAccessible = true }.get(demand) as Map<*, *>
            for ((scope, value) in entries) {
                if (field == "controls") { println("DEEP_GUIDANCE_CONTROL run=${config.index} scope=$scope rows=$value"); continue }
                val index = checkNotNull(value)
                if (field == "byMethod") {
                    val rows = index.javaClass.getDeclaredField("rows").apply { isAccessible = true }.get(index)
                    println("DEEP_GUIDANCE_DATA run=${config.index} scope=$scope rows=$rows")
                } else {
                    val data = index.javaClass.getDeclaredField("data").apply { isAccessible = true }.get(index)
                    val rows = data.javaClass.getDeclaredField("rows").apply { isAccessible = true }.get(data) as List<*>
                    val ports = index.javaClass.getDeclaredField("rowPorts").apply { isAccessible = true }.get(index) as List<*>
                    for (n in rows.indices) println("DEEP_GUIDANCE_DATA run=${config.index} scope=$scope exit=${ports[n]} row=${rows[n]}")
                    val controls = index.javaClass.getDeclaredField("controls").apply { isAccessible = true }.get(index)
                    println("DEEP_GUIDANCE_CONTROL run=${config.index} scope=$scope rows=$controls")
                }
            }
        }
    }
    @Test fun `exceptional ZERO normal demand keeps a four field source through the fifth run`() {
        DriverFixtures().use { f ->
            val p = f.program
            // while(true) { sourceAtFFFF(x); x=x.f; sinkRootT(x); }
            val b = p.method("deep-loop-no-leave", listOf(listOf(1), listOf(2), listOf(3),
                listOf(4), listOf(5), listOf(2), emptyList(), emptyList()),
                normalExit = 6, exceptionalExit = 7, backwardExitDiscovery = true).key()
            val arg = AccessPathBase.Argument(0)
            val x = AccessPathBase.LocalVar(0)
            val field = p.field("f")
            val t = MarkSlot.Concrete(p.mark("T"))
            p.statement(b, 1, MicroEdgeBuilder().apply { move(x, arg) }.build())
            val source = PathEdge(ZERO_FACT, PathFact(x, List(4) { field }, Tail.EXACT, t), ExclusionSet.Empty)
            fun plan(sourceCall: Boolean, sinks: List<SinkRule> = emptyList()) = CallPlan(setOf(x), listOf(
                CallStage.Edges(BEFORE, BOUND, BIND_IN, f.summary(keepEdge(x), ZERO_KEEP)),
                CallStage.Actions(BOUND, ADDED, emptyList()),
                CallStage.Edges(ADDED, RETURNED, if (sourceCall) SOURCES else UNRESOLVED,
                    if (sourceCall) f.summary(keepEdge(x), ZERO_KEEP, source) else f.summary(keepEdge(x), ZERO_KEEP)),
                CallStage.Actions(RETURNED, REWRITTEN, emptyList()),
                CallStage.Edges(REWRITTEN, AFTER, BIND_BACK, f.summary(keepEdge(x), ZERO_KEEP))
            ), sinks, BEFORE, AFTER)
            p.call(b, 3, plan(sourceCall = true))
            p.statement(b, 4, MicroEdgeBuilder().apply { read(x, x, listOf(field)) }.build())
            val sink = SinkRule(f.rule("deep-loop-root-sink"), 0, listOf(p.pattern(x, mark = t)), emptyList())
            p.call(b, 5, plan(sourceCall = false, sinks = listOf(sink)))
            val result = f.driver(FixedLimits(listOf(1, 1, 2, 3, 4, 5, 6)), 15.seconds,
                run1MarkMode = MarkMode.FULL, invokeRun = { config, shared, budget -> dumpDemand(config); f.run(config, shared, budget) }).analyze(listOf(b))
            for (run in f.results) {
                println("TRACE_RUN ${run.runIndex} ${run.status}")
                for (actor in run.analyzers) {
                    println("TRACE_STATS ${run.runIndex} ${actor.blockDiagnostics()}")
                    for ((pr, fs) in actor.summaries.all()) println("TRACE_ROOT ${run.runIndex} ${pr.members.map { it.toPattern() }} -> ${fs.layer} ${f.ops.leaves(fs).toList()}")
                    for (block in actor.blockSummaries()) for ((pr, fs) in block.summaries.all()) println("TRACE_BLOCK ${run.runIndex} $block ${pr.members.map { it.toPattern() }} -> ${fs.layer} ${f.ops.leaves(fs).toList()}")
                    for (scoped in actor.blockTargets()) for (target in scoped.rows) println("TRACE_BLOCK_TARGET ${run.runIndex} scope=${scoped.scope} exit=${scoped.exit} ${target.premise.members.map { it.toPattern() }} -> ${target.target}")
                    for (target in actor.targets) println("TRACE_TARGET ${run.runIndex} ${target.premise.members.map { it.toPattern() }} -> ${target.target}")
                }
            }
            val fifthConfig = f.configs.single { it.index == 5 }
            val repeatScope = BlockScope(BlockId(2),PortId(5))
            val repeatActual = p.pattern(x,List(3) { field },Tail.EXACT,t)
            val repeatFact = f.manager.factsOf(repeatActual.fact,repeatActual.exclusion,Layer.NORMAL)
            println("TRACE_REPEAT_QUERY $repeatScope actual=$repeatActual initials=${checkNotNull(fifthConfig.demand).scope(b,repeatScope).initials(repeatFact,fifthConfig.admissionPolicy)}")
            for (record in fifthConfig.records.byEntry(b,repeatScope,repeatActual)) println("TRACE_REPEAT_SAVED scope=$repeatScope dir=${record.direction} P=${record.premise.toPattern()} C=${f.ops.leaves(record.conclusion).toList()} layer=${record.conclusion.layer}")
            for (row in f.processed) if (row.run >= 1) println("TRACE_PROCESS ${row.run} ${row.delta.node} ${row.delta.premise.members.map { it.toPattern() }} -> ${row.delta.facts.layer} ${f.ops.leaves(row.delta.facts).toList()}")
            for (run in listOf(3, 5)) assertTrue(f.configs.single { it.index == run }.seeds
                .allowsSource(b, p.inst(b, 3), source), "run-$run keeps the same physical source permission")
            val third = f.results.single { it.runIndex == 3 }.analyzers.single { it.key == b }
            assertTrue(third.outgoingTargets.any { it.premise.isZero && it.target == Target.DemandTarget })
            assertFalse(third.targets.any { it.premise.isZero && it.target is Target.NormalTarget })
            assertEquals(5, result.end.run)
            assertEquals(1, result.entries.size)
            assertTrue(result.entries.any { it.descriptor.key.ruleId == "deep-loop-root-sink" })
            assertTrue(f.processed.none { it.run % 2 == 1 && it.delta.node.location.index in listOf(6, 7) })
        }
    }
}

